import{_ as e,o as t,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const a="/assets/cec62239767828bf.cSNT0bVW.png",o="/assets/58c2b1a2cd4c012b.BhKvstSO.png",p="/assets/77b1c6d7d9325898.talzKmv6.png",l="/assets/3fbbf14cb6c0dada.D9NPt0ke.png",c="/assets/b2afc1b626d94611.CXqWCanG.png",f=JSON.parse('{"title":"Windows系统设置禁Ping","description":"","frontmatter":{"title":"Windows系统设置禁Ping"},"headers":[],"relativePath":"ops-knowledge-base/operating-system/windows/disable-ping.md","filePath":"ops-knowledge-base/operating-system/windows/disable-ping.md","lastUpdated":1788259091000}'),r={name:"ops-knowledge-base/operating-system/windows/disable-ping.md"};function d(g,s,_,m,b,w){return t(),i("div",null,[...s[0]||(s[0]=[n('<p>为了防止他人通过网络ping扫描找到并攻击机器，可以在本机禁止ping命令</p><p><img src="'+a+'" alt=""></p><p>1.在电脑桌面使用快捷键win+R弹出运行窗口，在搜索框中输入cmd，点击确定</p><p><img src="'+o+'" alt=""></p><p>2.在命令窗口输入命令：</p><ul><li>netsh advfirewall firewall add rule name=&quot;ICMP Allow incoming V4 echo request&quot; protocol=icmpv4:8,any dir=in action=block</li></ul><p>这条命令就是在原有规则基础上新加了一条规则，如果我们想恢复禁Ping直接删掉这条规则即可：</p><ul><li>netsh advfirewall firewall del rule name=&quot;ICMP Allow incoming V4 echo request&quot;</li></ul><p><img src="'+p+'" alt=""></p><p>3.这时我们再查看IP已经禁Ping了，如果这时我们再想测试IP连通性，我们可以对端口进行Ping测试，这里可以看到是可以连通的，如果我们想恢复禁Ping可直接启动上述的规则即可</p><p><img src="'+l+'" alt=""></p><p><img src="'+c+'" alt=""></p>',12)])])}const P=e(r,[["render",d]]);export{f as __pageData,P as default};
